create table public.vp_territories(id uuid primary key default gen_random_uuid(),label text not null,west double precision not null,south double precision not null,east double precision not null,north double precision not null,claimed_by uuid references public.vp_accounts(user_id),claim_until timestamptz,source text,imported_at timestamptz,coverage text not null default 'Nicht importiert',created_at timestamptz not null default now(),check(west<east and south<north and west>=5 and east<=16 and south>=47 and north<=56));
create table public.vp_addresses(id uuid primary key default gen_random_uuid(),source_key text unique not null,street text not null,house_number text not null,city text not null,postal_code text not null default '',longitude double precision not null,latitude double precision not null,source text not null,imported_at timestamptz not null default now(),households integer check(households between 1 and 1000),status text not null default 'new' check(status in ('new','not_home','no_interest','appointment','qualified','customer','do_not_contact')),last_visit timestamptz,next_allowed_at timestamptz,blocked boolean not null default false,claimed_by uuid references public.vp_accounts(user_id),claim_until timestamptz,check(latitude between 47 and 56 and longitude between 5 and 16));
create index vp_addresses_area_idx on public.vp_addresses(city,latitude,longitude);
create table public.vp_d2d_contacts(id uuid primary key default gen_random_uuid(),address_id uuid not null references public.vp_addresses(id),owner_id uuid not null references public.vp_accounts(user_id),full_name text not null default '',phone text not null default '',email text not null default '',unit_label text not null default '',notes text not null default '',purpose text not null,privacy_notice_at timestamptz not null,phone_permission boolean not null default false,email_permission boolean not null default false,permission_evidence text not null default '',followup_at timestamptz,retain_until timestamptz not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(retain_until>created_at));
create table public.vp_d2d_visits(id uuid primary key default gen_random_uuid(),address_id uuid not null references public.vp_addresses(id),actor uuid not null references public.vp_accounts(user_id),status text not null,created_at timestamptz not null default now());
create function public.vp_claim_territory(p_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$declare t public.vp_territories%rowtype;begin
 perform public.vp_require_active();if not (select d2d_open from public.vp_settings where id) then raise exception 'D2D noch nicht freigegeben';end if;
 perform pg_advisory_xact_lock(472091);select * into t from public.vp_territories where id=p_id for update;if not found then raise exception 'Gebiet nicht gefunden';end if;
 if exists(select 1 from public.vp_territories x where x.id<>p_id and x.claimed_by<>auth.uid() and x.claim_until>now() and x.west<t.east and x.east>t.west and x.south<t.north and x.north>t.south) or (t.claimed_by is not null and t.claimed_by<>auth.uid() and t.claim_until>now()) then raise exception 'Gebiet überschneidet sich mit einer aktiven Reservierung';end if;
 update public.vp_territories set claimed_by=auth.uid(),claim_until=now()+make_interval(days=>(select claim_days from public.vp_settings where id)) where id=p_id;
 insert into public.vp_audit(actor,event,target) values(auth.uid(),'territory_claim',p_id::text);end$$;
create function public.vp_claim_address(p_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$declare a public.vp_addresses%rowtype;begin
 perform public.vp_require_active();if not (select d2d_open from public.vp_settings where id) then raise exception 'D2D noch nicht freigegeben';end if;
 select * into a from public.vp_addresses where id=p_id for update;if not found then raise exception 'Adresse nicht gefunden';end if;
 if a.blocked then raise exception 'Adresse ist für weitere Ansprache gesperrt';end if;
 if exists(select 1 from public.vp_territories t where t.claimed_by<>auth.uid() and t.claim_until>now() and a.longitude between t.west and t.east and a.latitude between t.south and t.north) then raise exception 'Adresse liegt in fremdem reserviertem Gebiet';end if;
 if a.claimed_by is distinct from auth.uid() and ((a.claim_until>now()) or (a.next_allowed_at>now())) then raise exception 'Adresse bereits reserviert oder in Kontaktsperrzeit';end if;
 update public.vp_addresses set claimed_by=auth.uid(),claim_until=now()+make_interval(days=>(select claim_days from public.vp_settings where id)) where id=p_id;end$$;
create function public.vp_qualify_address(p_id uuid,p_status text,p_households integer default null) returns void language plpgsql security definer set search_path=public,pg_temp as $$declare a public.vp_addresses%rowtype;begin
 perform public.vp_require_active();if not (select d2d_open from public.vp_settings where id) then raise exception 'D2D noch nicht freigegeben';end if;
 select * into a from public.vp_addresses where id=p_id for update;
 if not found or (not public.vp_is_admin() and (a.claimed_by is distinct from auth.uid() or a.claim_until<=now() or a.blocked)) then raise exception 'Keine gültige eigene Adressreservierung';end if;
 if p_status not in ('not_home','no_interest','appointment','qualified','customer','do_not_contact') then raise exception 'Ungültiger Qualifizierungsstatus';end if;
 update public.vp_addresses set status=p_status,households=coalesce(p_households,households),last_visit=now(),next_allowed_at=now()+make_interval(days=>(select cooldown_days from public.vp_settings where id)),blocked=blocked or p_status in ('no_interest','do_not_contact') where id=p_id;
 insert into public.vp_d2d_visits(address_id,actor,status) values(p_id,auth.uid(),p_status);end$$;
create function public.vp_save_contact(p_address uuid,p_contact uuid,p_data jsonb) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$declare i uuid;me uuid:=auth.uid();expires timestamptz;notice timestamptz;begin
 perform public.vp_require_active();if not (select d2d_open from public.vp_settings where id) then raise exception 'D2D noch nicht freigegeben';end if;
 if not public.vp_is_admin() and not exists(select 1 from public.vp_addresses where id=p_address and claimed_by=me and claim_until>now() and not blocked) then raise exception 'Eigene gültige Adressreservierung erforderlich';end if;
 if length(coalesce(p_data->>'purpose',''))<10 or p_data->>'privacy_notice_at' is null then raise exception 'Erhebungszweck und erteilte Datenschutzinformation dokumentieren';end if;
 expires=(p_data->>'retain_until')::timestamptz;notice=(p_data->>'privacy_notice_at')::timestamptz;
 if expires is null or expires<=now() or expires>now()+interval '180 days' or notice>now()+interval '5 minutes' then raise exception 'Prüf-/Löschfrist und Informationsdatum prüfen';end if;
 if (coalesce((p_data->>'phone_permission')::boolean,false) or coalesce((p_data->>'email_permission')::boolean,false)) and length(coalesce(p_data->>'permission_evidence',''))<10 then raise exception 'Konkreter Einwilligungs-/Kontaktwunschnachweis erforderlich';end if;
 if p_contact is not null then
 update public.vp_d2d_contacts set full_name=left(coalesce(p_data->>'full_name',''),160),phone=left(coalesce(p_data->>'phone',''),80),email=left(coalesce(p_data->>'email',''),200),unit_label=left(coalesce(p_data->>'unit_label',''),100),notes=left(coalesce(p_data->>'notes',''),3000),purpose=left(p_data->>'purpose',1000),privacy_notice_at=notice,phone_permission=coalesce((p_data->>'phone_permission')::boolean,false),email_permission=coalesce((p_data->>'email_permission')::boolean,false),permission_evidence=left(coalesce(p_data->>'permission_evidence',''),2000),followup_at=(p_data->>'followup_at')::timestamptz,retain_until=expires,updated_at=now() where id=p_contact and address_id=p_address and (owner_id=me or public.vp_is_admin()) returning id into i;
 if i is null then raise exception 'Kontakt nicht gefunden oder nicht berechtigt' using errcode='42501';end if;
 else
 insert into public.vp_d2d_contacts(address_id,owner_id,full_name,phone,email,unit_label,notes,purpose,privacy_notice_at,phone_permission,email_permission,permission_evidence,followup_at,retain_until) values(p_address,me,left(coalesce(p_data->>'full_name',''),160),left(coalesce(p_data->>'phone',''),80),left(coalesce(p_data->>'email',''),200),left(coalesce(p_data->>'unit_label',''),100),left(coalesce(p_data->>'notes',''),3000),left(p_data->>'purpose',1000),notice,coalesce((p_data->>'phone_permission')::boolean,false),coalesce((p_data->>'email_permission')::boolean,false),left(coalesce(p_data->>'permission_evidence',''),2000),(p_data->>'followup_at')::timestamptz,expires) returning id into i;
 end if;
 insert into public.vp_audit(actor,event,target) values(me,'contact_saved',i::text);return i;end$$;
create function public.vp_delete_contact(p_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$begin
 perform public.vp_require_active();delete from public.vp_d2d_contacts where id=p_id and (owner_id=auth.uid() or public.vp_is_admin());if not found then raise exception 'Kontakt nicht gefunden oder nicht berechtigt';end if;insert into public.vp_audit(actor,event,target) values(auth.uid(),'contact_deleted',p_id::text);end$$;
create function public.vp_admin_area(p_label text,p_bbox double precision[]) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$declare i uuid;begin
 perform public.vp_require_admin();if array_length(p_bbox,1)<>4 or length(p_label)<3 or p_bbox[3]-p_bbox[1]>.25 or p_bbox[4]-p_bbox[2]>.25 then raise exception 'Kleineres Gebiet wählen (max. 0,25 Grad je Seite)';end if;
 insert into public.vp_territories(label,west,south,east,north) values(left(p_label,200),p_bbox[1],p_bbox[2],p_bbox[3],p_bbox[4]) returning id into i;return i;end$$;
create function public.vp_import_addresses(p_territory uuid,p_rows jsonb,p_source text,p_coverage text) returns integer language plpgsql security definer set search_path=public,pg_temp as $$declare t public.vp_territories%rowtype;r jsonb;n integer:=0;begin
 perform public.vp_require_active();select * into t from public.vp_territories where id=p_territory;
 if not found or (not public.vp_is_admin() and t.claimed_by is distinct from auth.uid()) then raise exception 'Gebiet zuerst reservieren';end if;
 if jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows)>500 or length(p_source)<5 then raise exception 'Importumfang oder Quelle ungültig';end if;
 for r in select * from jsonb_array_elements(p_rows) loop
 if length(coalesce(r->>'source_key',''))<3 or length(coalesce(r->>'street',''))<1 or length(coalesce(r->>'house_number',''))<1 or length(coalesce(r->>'city',''))<1 or not ((r->>'longitude')::double precision between t.west and t.east and (r->>'latitude')::double precision between t.south and t.north) then raise exception 'Unvollständiger Adressdatensatz oder außerhalb des Gebiets';end if;
 insert into public.vp_addresses(source_key,street,house_number,city,postal_code,longitude,latitude,source) values(left(r->>'source_key',240),left(r->>'street',200),left(r->>'house_number',40),left(r->>'city',160),left(coalesce(r->>'postal_code',''),12),(r->>'longitude')::double precision,(r->>'latitude')::double precision,left(p_source,500)) on conflict(source_key) do nothing;n=n+1;
 end loop;
 update public.vp_territories set source=left(p_source,500),coverage=left(p_coverage,500),imported_at=now() where id=t.id;return n;end$$;
alter table public.vp_territories enable row level security;alter table public.vp_addresses enable row level security;alter table public.vp_d2d_contacts enable row level security;alter table public.vp_d2d_visits enable row level security;
revoke all on public.vp_territories,public.vp_addresses,public.vp_d2d_contacts,public.vp_d2d_visits from public,anon,authenticated;
grant select on public.vp_territories,public.vp_addresses,public.vp_d2d_contacts,public.vp_d2d_visits to authenticated;
create policy vp_territory_read on public.vp_territories for select to authenticated using(public.vp_is_active());
create policy vp_address_read on public.vp_addresses for select to authenticated using(public.vp_is_active());
create policy vp_contact_read on public.vp_d2d_contacts for select to authenticated using(public.vp_is_admin() or (owner_id=auth.uid() and public.vp_is_active() and retain_until>now()));
create policy vp_visit_read on public.vp_d2d_visits for select to authenticated using(public.vp_is_active());
revoke all on function public.vp_claim_territory(uuid),public.vp_claim_address(uuid),public.vp_qualify_address(uuid,text,integer),public.vp_save_contact(uuid,uuid,jsonb),public.vp_delete_contact(uuid),public.vp_admin_area(text,double precision[]),public.vp_import_addresses(uuid,jsonb,text,text) from public,anon,authenticated;
grant execute on function public.vp_claim_territory(uuid),public.vp_claim_address(uuid),public.vp_qualify_address(uuid,text,integer),public.vp_save_contact(uuid,uuid,jsonb),public.vp_delete_contact(uuid),public.vp_admin_area(text,double precision[]),public.vp_import_addresses(uuid,jsonb,text,text) to authenticated;
